mapper.select:
SELECT id, answer_id, event_type, event_data, occurred_at
FROM qa_answer_event
WHERE answer_id = #{answerId}
  AND id > #{afterSequence}
ORDER BY id ASC
LIMIT #{limit}

SELECT COUNT(1)
FROM qa_answer_event
WHERE answer_id = #{answerId}
  AND id = #{sequence}

SELECT e.id, e.answer_id, e.event_type, e.event_data, e.occurred_at FROM qa_answer_event e INNER JOIN qa_answer a ON a.public_id = e.answer_id INNER JOIN qa_conversation c ON c.public_id = a.conversation_id WHERE c.public_id = #{conversationId} AND c.owner_id = #{ownerId} AND c.deleted_at IS NULL AND e.event_type NOT IN ('delta', 'metadata') AND e.answer_id IN
#{answerId}
ORDER BY e.id ASC
